{
  "application": "poster-generation",
  "case_id": "case-education-unicef-every-child-learns",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A1-portrait",
    "audience": "public-exhibition",
    "tone": "bold, warm",
    "venue": null
  },
  "brief": {
    "title": "Every Child Deserves to Learn",
    "one_liner": "Millions of children worldwide are still denied their right to quality education — UNICEF is working to change that.",
    "goal": "Viewers should understand the scale of the global education crisis, recognize the key barriers children face, and feel motivated to support efforts ensuring every child has access to inclusive, quality education."
  },
  "sections": [
    {
      "id": "crisis-overview",
      "title": "The Global Education Crisis",
      "objective": "Present the scale of the problem with hard-hitting statistics on out-of-school children and learning poverty."
    },
    {
      "id": "barriers",
      "title": "Barriers to Education",
      "objective": "Highlight the main obstacles — conflict, poverty, gender inequality, disability, and climate change — that keep children out of school."
    },
    {
      "id": "unicef-focus-areas",
      "title": "UNICEF's Education Focus Areas",
      "objective": "Summarize UNICEF's key programmatic pillars for improving education outcomes worldwide."
    },
    {
      "id": "call-to-action",
      "title": "What Can Be Done",
      "objective": "Inspire action by outlining concrete steps and the vision of education as a fundamental child right aligned with the Sustainable Development Goals."
    }
  ],
  "metrics": [
    {
      "label": "Children out of school globally",
      "value": "250 million"
    },
    {
      "label": "Children not achieving minimum reading proficiency by age 10",
      "value": "70%"
    },
    {
      "label": "Countries where UNICEF operates education programmes",
      "value": "190+"
    },
    {
      "label": "Girls more likely to be excluded from education in crisis settings",
      "value": "2.5× more likely"
    },
    {
      "label": "Children with disabilities out of school in low-income countries",
      "value": "~49%"
    }
  ]
}

