[metadata] {"type": "create", "filePath": "/app/output/every-child-deserves-to-learn-infographic.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Every Child Deserves to Learn - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { width: 100%; height: 100%; background: #f0f9ff; }
    #container { width: 100%; height: 100vh; min-height: 900px; }
    #export-btn {
      position: fixed; top: 16px; right: 16px; z-index: 9999;
      background: #0093d0; color: white; border: none; border-radius: 8px;
      padding: 10px 20px; font-size: 14px; cursor: pointer; font-family: sans-serif;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }
    #export-btn:hover { background: #007bb0; }
  </style>
</head>
<body>
  <button id="export-btn" onclick="exportSVG()">Export SVG</button>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const syntax = `infographic list-waterfall-compact-card
data
  title Every Child Deserves to Learn
  desc 250 MILLION children are out of school worldwide — a global crisis demanding urgent action
  lists
    - label 250 Million
      desc Children & adolescents out of school globally
      icon person 3 fill
    - label 70%
      desc Children in low/middle-income countries cannot read by age 10
      icon book fill
    - label Armed Conflict
      desc Girls are 2.5× more likely to be excluded from school in crisis settings
      icon warning fill
    - label Poverty
      desc Families cannot afford fees, uniforms, or supplies — children work instead of learning
      icon currency dollar fill
    - label Gender Inequality
      desc Social norms limit girls' access, especially at secondary level
      icon person 2 fill
    - label ~49% Disabled
      desc Children with disabilities in low-income countries never enter a classroom
      icon figure accessibility fill
    - label Climate Shocks
      desc Floods, droughts & extreme weather disrupt schooling for the most vulnerable
      icon cloud rain fill
    - label UNICEF in 190+ Countries
      desc Early childhood, inclusive education, emergencies, digital learning & skills
      icon globe americas fill
    - label SDG 4
      desc Inclusive, equitable, quality education for all — no child left behind
      icon star fill
theme
  palette #0093d0 #00aeef #f5a623 #e8830a #005b96 #009b77 #e63946 #2ec4b6 #ff9f1c
`;

    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: '100%',
      height: '100%',
    });

    infographic.render(syntax);

    document.fonts?.ready.then(() => {
      infographic.render(syntax);
    }).catch((error) => console.error('Error waiting for fonts:', error));

    async function exportSVG() {
      try {
        const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
        const a = document.createElement('a');
        a.href = svgDataUrl;
        a.download = 'every-child-deserves-to-learn.svg';
        a.click();
      } catch (e) {
        console.error('Export failed:', e);
        alert('Export failed: ' + e.message);
      }
    }
  </script>
</body>
</html>
