const syntax = `infographic list-waterfall-compact-card
data
  title Every Child Deserves to Learn
  desc 250 MILLION children are out of school worldwide — a global crisis demanding urgent action
  lists
    - label 250 Million
      desc Children & adolescents out of school globally
      icon person 3 fill
    - label 70%
      desc Cannot read a simple text by age 10 (low/middle-income countries)
      icon book fill
    - label Armed Conflict
      desc Girls are 2.5× more likely to be excluded from school in crisis settings
      icon warning fill
    - label Poverty
      desc Families cannot afford fees, uniforms, or supplies — children work instead
      icon currency dollar fill
    - label Gender Inequality
      desc Social norms restrict girls' access, especially at secondary level
      icon person 2 fill
    - label ~49% With Disabilities
      desc Children with disabilities in low-income countries never enter a classroom
      icon figure accessibility fill
    - label Climate Shocks
      desc Floods, droughts & extreme weather disrupt schooling for the most vulnerable
      icon cloud rain fill
    - label UNICEF in 190+ Countries
      desc Early childhood, inclusive & emergency education, digital learning & skills
      icon globe americas fill
    - label SDG 4 — Act Now
      desc Inclusive, equitable, quality education for all — no child left behind
      icon star fill
theme
  palette #0093d0 #00aeef #f5a623 #e8830a #005b96 #009b77 #e63946 #2ec4b6 #ff9f1c
`;

try {
  const svgString = await renderToString(syntax);
  writeFileSync('/app/output/final_poster.svg', svgString, 'utf8');
  console.log('SVG written successfully');
  console.log('SVG length:', svgString.length);
  console.log('First 200 chars:', svgString.slice(0, 200));
} catch (err) {
  console.error('Render error:', err.message);
  console.error(err.stack);
  process.exit(1);
}

